import React from 'react';
import { C } from '../data';
import FadeIn from './FadeIn';

export default function SectionHeader({ tag, title, subtitle }) {
  return (
    <FadeIn className="text-center mb-20">
      {/* --- Ultra-Professional Tag --- */}
      <div
        className="inline-block px-6 py-2 rounded-lg text-[11px] font-black uppercase tracking-[0.3em] mb-6"
        style={{ 
          background: 'rgba(245,166,35,0.05)', 
          color: C.gold,
          borderBottom: `2px solid ${C.gold}`, // Bottom line for a unique look
        }}
      >
        {tag}
      </div>

      {/* --- Bold & Dominant Title --- */}
      <h2
        className="text-4xl md:text-6xl font-black mb-8" // font-black used for extra bold look
        style={{ 
          color: '#0f172a', // Deep corporate blue/black
          fontFamily: "'Playfair Display', serif",
          lineHeight: 1.05,
          letterSpacing: '-0.03em' // Tighter tracking for bold headings
        }}
      >
        {title}
      </h2>

      {/* --- Refined Subtitle --- */}
      {subtitle && (
        <div style={{ position: 'relative', display: 'inline-block' }}>
          <p 
            className="text-lg md:text-xl max-w-2xl mx-auto leading-relaxed" 
            style={{ 
              color: '#4b5563', 
              fontWeight: 450,
              paddingBottom: '20px'
            }}
          >
            {subtitle}
          </p>

          {/* Professional Accent Line - Centered */}
          <div 
            style={{ 
              width: '80px', 
              height: '4px', 
              background: C.gold, 
              margin: '0 auto',
              borderRadius: '10px'
            }} 
          />
        </div>
      )}
    </FadeIn>
  );
}
